insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-59','5-3',59,'不断','bú duàn','không ngừng','这个问题需要不断解决。','Zhège wèntí xūyào bùduàn jiějué.','Vấn đề này cần phải giải quyết liên tục.');
