insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-61','5-4',61,'不耐烦','bú nài fán','chán nản, không kiên nhẫn','他对等待变得不耐烦了。','Tā duì děngdài biàn dé bù nàifán le.','Anh ấy trở nên không kiên nhẫn với việc chờ đợi.');
