insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-63','5-4',63,'不如','bú rú','không bằng','这次会议不如上次好。','Zhè cì huìyì bùrú shàng cì hǎo.','Cuộc họp lần này không bằng lần trước.');
