insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-103','5-6',103,'称呼','chēng hū','xưng hô','请问怎么称呼呢？','Qǐngwèn zěnme chēnghu ne?','Xin hỏi xưng hô thế nào nhỉ?');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-104','5-6',104,'称赞','chēng zàn','tán thưởng','她称赞了我的工作。','Tā chēngzànle wǒ de gōngzuò.','Cô ấy khen ngợi công việc của tôi.');
