insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-106','5-6',106,'成果','chéng guǒ','thành quả','我们取得了很好的成果。','Wǒmen qǔdéle hěn hǎo de chéngguǒ.','Chúng tôi đã đạt được kết quả rất tốt.');
