insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-108','5-6',108,'成立','chéng lì','thành lập','这个公司刚刚成立。','Zhège gōngsī gānggāng chénglì.','Công ty này vừa mới được thành lập.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-109','5-6',109,'成人','chéng rén','người lớn','除了最小的女儿外，‌其他孩子都已成人。‌','Chú le zuì xiǎo de nǚ''ér wài,‌qítā háizi dōu yǐ chéngrén.‌','Ngoại trừ cô con gái út, những đứa trẻ khác đều đã trưởng thành. ‌');
