insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-111','5-6',111,'成语','chéng yǔ','thành ngữ','这是一句成语，很有意思。','Zhè shì yī jù chéngyǔ, hěn yǒu yìsi.','Đây là một câu thành ngữ, rất thú vị.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-112','5-6',112,'成长','chéng zhǎng','trưởng thành','孩子们在健康成长。','Háizimen zài jiànkāng chéngzhǎng.','Những đứa trẻ đang trưởng thành khỏe mạnh.');
